typedef float rational_t;
extern "C" float sqrtf(float);

class vector3d {
public:
  rational_t x, y, z;
  vector3d() {}
  vector3d(rational_t X, rational_t Y, rational_t Z) : x(X), y(Y), z(Z) {}
  rational_t length() const { return sqrtf(x*x + y*y + z*z); }
};
inline vector3d operator-(const vector3d& a, const vector3d& b) { return vector3d(a.x-b.x, a.y-b.y, a.z-b.z); }

class collision_geometry {
public:
  enum { NONE, CAPSULE, MESH };
  unsigned int get_type() const;
  rational_t get_radius() const;
};
class entity {
public:
  collision_geometry* get_colgeom() const;
  virtual void set_radius(rational_t);
  virtual rational_t get_radius() const;
  const vector3d& get_abs_position() const;
};
class conglomerate : public entity {
  char padding[500];
  entity** members_begin;
  entity** members_end;
public:
  void compute_radius();
};

void conglomerate::compute_radius()
{
//  set_rel_po( po_identity_matrix );
//  update_abs_po();

  // can take radius from collision mesh, if any
  collision_geometry* cg = get_colgeom();
  if ( cg && cg->get_type()==collision_geometry::MESH )
  {
    set_radius( cg->get_radius() );
  }

  entity** i = members_begin;
  entity** i_end = members_end;
  for ( ; i!=i_end; ++i )
  {
    entity* e = *i;
    rational_t r = (e->get_abs_position()-get_abs_position()).length() + e->get_radius();
    if ( r > get_radius() )
      set_radius( r );
  }
}
